/*!40000 ALTER TABLE `media_album` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `media_photo`
--

DROP TABLE IF EXISTS `media_photo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `media_photo` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `album_id` varchar(16) NOT NULL COMMENT '所属相册 id',
  `seq` int NOT NULL COMMENT '册内序号（从 0 开始，对应原站 i）',
  `rel_path` varchar(700) NOT NULL COMMENT '图片路径（相对媒体根）',
  `bytes` bigint NOT NULL DEFAULT '0' COMMENT '文件字节数（源索引未提供时为 0）',
  `w` int DEFAULT NULL COMMENT '宽度像素',
  `h` int DEFAULT NULL COMMENT '高度像素',
  `is_big` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否大图：1 需生成 preview 大图',
  `hidden` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否隐藏：0 显示 / 1 隐藏',
  `missing` tinyint NOT NULL DEFAULT '0' COMMENT '缺失标记：1=扫描时磁盘上不存在，0=正常',
  `last_seen` datetime DEFAULT NULL COMMENT '最后一次在磁盘上看到该文件的扫描时间（缺失行即「最后 seen」）',
  `content_hash` char(16) DEFAULT NULL COMMENT '内容哈希(oshash)，用于相册内新增图片后不错位',
  `root_id` int DEFAULT NULL COMMENT '所属库根 media_root.id，NULL=默认根',
